def sameCircle(n, friendships, queries):
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in friendships:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    return [1 if find(x) == find(y) else 0 for x, y in queries]
